var messageCatalogs = func() map[string]map[string]string {
	locales := [...]string{"en", "zh-CN", "zh-TW", "ja", "fr", "de"}
	catalogs := make(map[string]map[string]string, len(locales))
	for index, locale := range locales {
		catalog := make(map[string]string, len(messageTable))
		for key, values := range messageTable {
			catalog[key] = values[index]
		}
		catalogs[locale] = catalog
	}
	return catalogs
}()
